export const printYearlyReport = (year: number, transactions: Transaction[]) => {
  let totIn = 0, totOut = 0;
  const rows = MONTHS.map((monthName, i) => {
    let mIn = 0, mOut = 0;
    transactions.forEach(t => {
      const d = new Date(t.date);
      if (d.getFullYear() === year && d.getMonth() === i) {
        if (t.type === 'in') mIn += t.amount; else mOut += t.amount;
      }
    });
    totIn += mIn; totOut += mOut;
    const net = mIn - mOut;
    return `
      <tr>
        <td class="p-3 border-b">${monthName}</td>
        <td class="p-3 border-b text-right text-emerald-600">${formatRM(mIn)}</td>
        <td class="p-3 border-b text-right text-rose-600">${formatRM(mOut)}</td>
        <td class="p-3 border-b text-right font-bold ${net < 0 ? 'text-red-500' : 'text-indigo-600'}">${formatRM(net)}</td>
      </tr>
    `;
  }).join('');

  const win = window.open('', '', 'width=900,height=700');
  if (!win) return;

  win.document.write(`
    <html><head><title>Laporan Tahunan ${year}</title>
    <script src="https://cdn.tailwindcss.com"></script>
    </head><body class="p-8 font-sans">
      <h1 class="text-2xl font-bold mb-6 text-gray-800">Laporan Untung Rugi Tahunan ${year}</h1>
      <table class="w-full text-sm text-left border border-gray-300">
        <thead class="bg-gray-800 text-white font-bold">
            <tr>
                <th class="p-3">Bulan</th>
                <th class="p-3 text-right">Pendapatan (Masuk)</th>
                <th class="p-3 text-right">Perbelanjaan (Keluar)</th>
                <th class="p-3 text-right">Untung/Rugi Bersih</th>
            </tr>
        </thead>
        <tbody>${rows}</tbody>
        <tfoot class="bg-gray-100 font-bold border-t-2 border-gray-300">
            <tr>
                <td class="p-3">JUMLAH BESAR</td>
                <td class="p-3 text-right text-emerald-600">${formatRM(totIn)}</td>
                <td class="p-3 text-right text-rose-600">${formatRM(totOut)}</td>
                <td class="p-3 text-right text-indigo-700">${formatRM(totIn - totOut)}</td>
            </tr>
        </tfoot>
    </table>
    <div class="mt-4 text-sm text-gray-500">Dicetak pada: ${new Date().toLocaleString()}</div>
    <script>setTimeout(()=>{window.print();},500);</script>
    </body></html>
  `);
  win.document.close();
};

import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import { ACCOUNTS, CATEGORIES, Transaction } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onSave: (t: Omit<Transaction, 'id'>) => void;
  initialData?: Transaction | null;
}

const TransactionFormModal: React.FC<Props> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    account: ACCOUNTS[0],
    amount: '',
    name: '',
    category: '',
    details: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        date: initialData.date,
        type: initialData.type,
        account: initialData.account,
        amount: initialData.amount.toString(),
        name: initialData.name,
        category: initialData.category,
        details: initialData.details
      });
    } else {
      // Reset to defaults
      setFormData({
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: ACCOUNTS[0],
        amount: '',
        name: '',
        category: '',
        details: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      amount: parseFloat(formData.amount) || 0
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white w-full max-w-lg rounded-xl shadow-2xl overflow-y-auto max-h-[90vh] animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 py-4 border-b bg-gray-50 rounded-t-xl">
          <p className="text-lg font-bold text-gray-800">{initialData ? 'Salin Rekod' : 'Rekod Baru'}</p>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tarikh</label>
              <input
                type="date"
                required
                className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                value={formData.date}
                onChange={e => setFormData({ ...formData, date: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Jenis</label>
              <select
                className={`w-full border border-gray-300 rounded-lg p-2.5 text-sm font-bold focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none ${formData.type === 'in' ? 'text-emerald-600' : 'text-rose-600'}`}
                value={formData.type}
                onChange={e => setFormData({ ...formData, type: e.target.value as 'in' | 'out' })}
              >
                <option value="in" className="text-emerald-600">Masuk (Income)</option>
                <option value="out" className="text-rose-600">Keluar (Expense)</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-indigo-600 uppercase mb-1">Akaun</label>
            <select
              className="w-full border border-gray-300 bg-indigo-50 rounded-lg p-2.5 text-sm font-bold text-indigo-900 focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.account}
              onChange={e => setFormData({ ...formData, account: e.target.value })}
            >
              {ACCOUNTS.map(acc => <option key={acc} value={acc}>{acc}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Jumlah (RM)</label>
            <input
              type="number"
              step="0.01"
              required
              placeholder="0.00"
              className="w-full border border-gray-300 rounded-lg p-2.5 text-lg font-mono font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.amount}
              onChange={e => setFormData({ ...formData, amount: e.target.value })}
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nama Payer/Payee</label>
            <input
              type="text"
              required
              placeholder="Nama..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kategori</label>
            <input
              list="categories"
              placeholder="Pilih atau taip..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.category}
              onChange={e => setFormData({ ...formData, category: e.target.value })}
            />
            <datalist id="categories">
              {CATEGORIES.map(c => <option key={c} value={c} />)}
            </datalist>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Butiran</label>
            <input
              type="text"
              placeholder="Keterangan lanjut..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.details}
              onChange={e => setFormData({ ...formData, details: e.target.value })}
            />
          </div>

          <div className="pt-4 flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg font-medium hover:bg-gray-200 transition-colors"
            >
              Batal
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-slate-800 text-white rounded-lg font-medium hover:bg-slate-900 transition-colors shadow-lg"
            >
              Simpan
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TransactionFormModal;

import React, { useState } from 'react';
import { X, Printer, Trash2, Banknote } from 'lucide-react';
import { Invoice, Transaction } from '../types';
import { printInvoice, formatRM } from '../utils/printUtils';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  invoices: Invoice[];
  onAddInvoice: (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => void;
  onDeleteInvoice: (id: number) => void;
  onPayInvoice: (inv: Invoice) => void;
}

const InvoiceModal: React.FC<Props> = ({ isOpen, onClose, invoices, onAddInvoice, onDeleteInvoice, onPayInvoice }) => {
  const [formData, setFormData] = useState({
    no: '',
    client: '',
    desc: '',
    amount: ''
  });

  if (!isOpen) return null;

  const handleSubmit = () => {
    if (!formData.no || !formData.client || !formData.amount) return alert("Sila isi maklumat invois");

    onAddInvoice({
      no: formData.no,
      client: formData.client,
      desc: formData.desc,
      amount: parseFloat(formData.amount)
    });

    setFormData({ no: '', client: '', desc: '', amount: '' });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-4xl h-[90vh] rounded-xl shadow-2xl flex flex-col animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 py-4 border-b bg-blue-50 rounded-t-xl">
          <p className="text-lg font-bold text-blue-800 flex items-center gap-2">
            Pengurusan Invois
          </p>
          <button onClick={onClose} className="p-2 hover:bg-blue-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-blue-800" />
          </button>
        </div>

        <div className="flex-1 overflow-hidden p-6 flex flex-col md:flex-row gap-6">
          {/* Form */}
          <div className="w-full md:w-1/3 bg-gray-50 p-4 rounded-lg border border-gray-200 h-fit">
            <h3 className="font-bold text-gray-700 mb-3">Jana Invois Baru</h3>
            <div className="space-y-3">
              <input 
                placeholder="No. Invois (Cth: INV-2025-001)" 
                className="w-full border border-gray-300 rounded-lg p-2 text-sm"
                value={formData.no}
                onChange={e => setFormData({...formData, no: e.target.value})}
              />
              <input 
                placeholder="Nama Pelanggan" 
                className="w-full border border-gray-300 rounded-lg p-2 text-sm"
                value={formData.client}
                onChange={e => setFormData({...formData, client: e.target.value})}
              />
              <textarea 
                placeholder="Keterangan Caj..." 
                className="w-full border border-gray-300 rounded-lg p-2 text-sm h-20 resize-none"
                value={formData.desc}
                onChange={e => setFormData({...formData, desc: e.target.value})}
              />
              <input 
                type="number" 
                placeholder="Jumlah (RM)" 
                className="w-full border border-gray-300 rounded-lg p-2 text-sm font-mono"
                value={formData.amount}
                onChange={e => setFormData({...formData, amount: e.target.value})}
              />
              <button onClick={handleSubmit} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 mt-2 transition-colors">
                Buat Invois
              </button>
            </div>
          </div>

          {/* List */}
          <div className="w-full md:w-2/3 flex flex-col">
            <h3 className="font-bold text-gray-700 mb-3">Senarai Invois</h3>
            <div className="flex-1 overflow-auto border rounded-lg bg-white">
              <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs sticky top-0">
                  <tr>
                    <th className="p-3">No. Invois</th>
                    <th className="p-3">Pelanggan</th>
                    <th className="p-3 text-right">Jumlah</th>
                    <th className="p-3 text-center">Status</th>
                    <th className="p-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {[...invoices].reverse().map(inv => (
                    <tr key={inv.id} className="hover:bg-gray-50">
                      <td className="p-3 font-mono text-xs font-bold text-gray-600">{inv.no}</td>
                      <td className="p-3">{inv.client}</td>
                      <td className="p-3 text-right font-bold">{formatRM(inv.amount)}</td>
                      <td className="p-3 text-center">
                        <span className={`px-2 py-1 rounded text-xs font-bold ${inv.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                          {inv.status === 'paid' ? 'DIBAYAR' : 'BELUM'}
                        </span>
                      </td>
                      <td className="p-3 flex justify-center gap-2">
                        <button onClick={() => printInvoice(inv)} className="text-blue-600 hover:text-blue-800" title="Cetak">
                          <Printer className="w-4 h-4" />
                        </button>
                        {inv.status === 'unpaid' && (
                          <button onClick={() => onPayInvoice(inv)} className="text-green-600 hover:text-green-800" title="Bayar">
                            <Banknote className="w-4 h-4" />
                          </button>
                        )}
                        <button onClick={() => onDeleteInvoice(inv.id)} className="text-red-400 hover:text-red-600" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {invoices.length === 0 && (
                    <tr>
                      <td colSpan={5} className="p-8 text-center text-gray-400">Tiada inbois direkodkan.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default InvoiceModal;

import React from 'react';
import { X, Printer } from 'lucide-react';
import { Transaction, MONTHS } from '../types';
import { printYearlyReport, formatRM } from '../utils/printUtils';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  transactions: Transaction[];
  year: number;
}

const ReportModal: React.FC<Props> = ({ isOpen, onClose, transactions, year }) => {
  if (!isOpen) return null;

  let grandTotalIn = 0;
  let grandTotalOut = 0;

  const monthlyData = MONTHS.map((monthName, index) => {
    let monthlyIn = 0;
    let monthlyOut = 0;

    transactions.forEach(t => {
      const d = new Date(t.date);
      if (d.getFullYear() === year && d.getMonth() === index) {
        if (t.type === 'in') monthlyIn += t.amount;
        else monthlyOut += t.amount;
      }
    });

    grandTotalIn += monthlyIn;
    grandTotalOut += monthlyOut;

    return { name: monthName, in: monthlyIn, out: monthlyOut, net: monthlyIn - monthlyOut };
  });

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-4xl rounded-xl shadow-2xl overflow-y-auto max-h-[90vh] animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 py-4 border-b bg-purple-50 rounded-t-xl">
          <p className="text-lg font-bold text-purple-800">Laporan Untung Rugi Tahunan</p>
          <button onClick={onClose} className="p-2 hover:bg-purple-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-purple-800" />
          </button>
        </div>

        <div className="p-6">
          <div className="flex justify-between mb-4 items-center">
            <h3 className="text-xl font-bold text-gray-800">Tahun {year}</h3>
            <button 
              onClick={() => printYearlyReport(year, transactions)}
              className="bg-gray-800 hover:bg-gray-900 text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-colors"
            >
              <Printer className="w-4 h-4" /> Cetak
            </button>
          </div>

          <div className="overflow-x-auto border border-gray-200 rounded-lg">
            <table className="w-full text-sm text-left">
              <thead className="bg-gray-800 text-white font-bold">
                <tr>
                  <th className="p-3">Bulan</th>
                  <th className="p-3 text-right">Pendapatan (Masuk)</th>
                  <th className="p-3 text-right">Perbelanjaan (Keluar)</th>
                  <th className="p-3 text-right">Untung/Rugi Bersih</th>
                </tr>
              </thead>
              <tbody className="divide-y font-mono text-gray-700">
                {monthlyData.map((m, i) => (
                  <tr key={i} className="hover:bg-gray-50">
                    <td className="p-3">{m.name}</td>
                    <td className="p-3 text-right text-emerald-600">{formatRM(m.in)}</td>
                    <td className="p-3 text-right text-rose-600">{formatRM(m.out)}</td>
                    <td className={`p-3 text-right font-bold ${m.net < 0 ? 'text-rose-600' : 'text-indigo-600'}`}>
                      {formatRM(m.net)}
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-gray-100 font-bold border-t-2 border-gray-300">
                <tr>
                  <td className="p-3">JUMLAH BESAR</td>
                  <td className="p-3 text-right text-emerald-600">{formatRM(grandTotalIn)}</td>
                  <td className="p-3 text-right text-rose-600">{formatRM(grandTotalOut)}</td>
                  <td className="p-3 text-right text-indigo-700">{formatRM(grandTotalIn - grandTotalOut)}</td>
                </tr>
              </tfoot>
            </table>
          </div>
          <p className="text-xs text-gray-500 mt-3">* Laporan ini merangkumi semua akaun yang didaftarkan.</p>
        </div>
      </div>
    </div>
  );
};

export default ReportModal;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle 
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleAddTransaction = (t: Omit<Transaction, 'id'>) => {
    const newTrans = { ...t, id: Date.now() };
    setTransactions(prev => [...prev, newTrans]);
    setEditingTransaction(null); // Clear copy state if any
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-amber-500 p-2 rounded-lg text-slate-900">
                <Scale className="w-6 h-6" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 mr-2">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-md transition" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-md transition cursor-pointer border border-slate-600" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-md transition ml-2" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg p-2 font-bold cursor-pointer hover:bg-gray-100"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg p-2 font-bold cursor-pointer hover:bg-gray-100"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { setEditingTransaction(null); setIsAddModalOpen(true); }}
              className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-6 py-2 rounded-lg shadow-md transition font-medium flex items-center justify-center gap-2"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-emerald-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.in)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-rose-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Keluar</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-indigo-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Baki (Mengikut Filter)</p>
              <p className={`text-2xl font-bold mt-1 ${totals.bal < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                {formatRM(totals.bal)}
              </p>
            </div>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Scale className="w-4 h-4 text-blue-500" /> Aliran Tunai (Keseluruhan Tahun {filterYear})
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData.barData}>
                    <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `RM${v/1000}k`} />
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Bar dataKey="Masuk" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="Keluar" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Table className="w-4 h-4 text-purple-500" /> Pecahan Belanja
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData.pieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.pieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Legend iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Ledger Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center bg-gray-50 gap-4">
              <h2 className="font-bold text-gray-800 flex items-center gap-2">
                <Table className="w-4 h-4 text-gray-500" /> Lejer Transaksi
              </h2>
              <div className="relative w-full sm:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, butiran..."
                  className="pl-10 w-full border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:ring-1 focus:ring-indigo-500 outline-none"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-gray-100 text-gray-600 uppercase text-xs font-bold">
                  <tr>
                    <th className="px-4 py-3">Tarikh</th>
                    <th className="px-4 py-3">Akaun</th>
                    <th className="px-4 py-3">Butiran</th>
                    <th className="px-4 py-3 text-right">Masuk</th>
                    <th className="px-4 py-3 text-right">Keluar</th>
                    <th className="px-4 py-3 text-center">Dokumen</th>
                    <th className="px-4 py-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-gray-500 text-xs font-mono">{formatDate(t.date)}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-1 rounded text-xs font-bold bg-indigo-50 text-indigo-700">{t.account}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-gray-800 text-sm">{t.name}</div>
                        <div className="text-xs text-gray-500">{t.details}</div>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-emerald-600">
                        {t.type === 'in' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-rose-600">
                        {t.type === 'out' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button 
                          onClick={() => printReceipt(t)}
                          className="text-xs border px-2 py-1 rounded bg-white hover:bg-gray-100 text-gray-600 transition-colors"
                        >
                          <Printer className="w-3 h-3 inline mr-1" /> Cetak
                        </button>
                      </td>
                      <td className="px-4 py-3 text-center flex justify-center gap-2">
                        <button onClick={() => handleDuplicate(t)} className="text-blue-400 hover:text-blue-600" title="Salin">
                          <Copy className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteTransaction(t.id)} className="text-gray-300 hover:text-red-500" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredTransactions.length === 0 && (
                    <tr>
                      <td colSpan={7} className="py-12 text-center text-gray-500">Tiada rekod dijumpai.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      <TransactionFormModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        onSave={handleAddTransaction}
        initialData={editingTransaction}
      />

      <InvoiceModal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        invoices={invoices}
        onAddInvoice={handleAddInvoice}
        onDeleteInvoice={handleDeleteInvoice}
        onPayInvoice={handlePayInvoice}
      />

      <ReportModal 
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
        transactions={transactions}
        year={filterYear}
      />
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error('Failed to find the root element');

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';
import { ACCOUNTS, CATEGORIES, Transaction } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onSave: (t: Omit<Transaction, 'id'>) => void;
  initialData?: Transaction | null;
  mode?: 'create' | 'edit' | 'copy';
}

const TransactionFormModal: React.FC<Props> = ({ isOpen, onClose, onSave, initialData, mode = 'create' }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    account: ACCOUNTS[0],
    amount: '',
    name: '',
    category: '',
    details: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        date: initialData.date,
        type: initialData.type,
        account: initialData.account,
        amount: initialData.amount.toString(),
        name: initialData.name,
        category: initialData.category,
        details: initialData.details
      });
    } else {
      // Reset to defaults
      setFormData({
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: ACCOUNTS[0],
        amount: '',
        name: '',
        category: '',
        details: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      amount: parseFloat(formData.amount) || 0
    });
    onClose();
  };

  const getTitle = () => {
    if (mode === 'edit') return 'Kemaskini Rekod';
    if (mode === 'copy') return 'Salin Rekod';
    return 'Rekod Baru';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white w-full max-w-lg rounded-xl shadow-2xl overflow-y-auto max-h-[90vh] animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 py-4 border-b bg-gray-50 rounded-t-xl">
          <p className="text-lg font-bold text-gray-800">{getTitle()}</p>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tarikh</label>
              <input
                type="date"
                required
                className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                value={formData.date}
                onChange={e => setFormData({ ...formData, date: e.target.value })}
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Jenis</label>
              <select
                className={`w-full border border-gray-300 rounded-lg p-2.5 text-sm font-bold focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none ${formData.type === 'in' ? 'text-emerald-600' : 'text-rose-600'}`}
                value={formData.type}
                onChange={e => setFormData({ ...formData, type: e.target.value as 'in' | 'out' })}
              >
                <option value="in" className="text-emerald-600">Masuk (Income)</option>
                <option value="out" className="text-rose-600">Keluar (Expense)</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-indigo-600 uppercase mb-1">Akaun</label>
            <select
              className="w-full border border-gray-300 bg-indigo-50 rounded-lg p-2.5 text-sm font-bold text-indigo-900 focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.account}
              onChange={e => setFormData({ ...formData, account: e.target.value })}
            >
              {ACCOUNTS.map(acc => <option key={acc} value={acc}>{acc}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Jumlah (RM)</label>
            <input
              type="number"
              step="0.01"
              required
              placeholder="0.00"
              className="w-full border border-gray-300 rounded-lg p-2.5 text-lg font-mono font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.amount}
              onChange={e => setFormData({ ...formData, amount: e.target.value })}
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nama Payer/Payee</label>
            <input
              type="text"
              required
              placeholder="Nama..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kategori</label>
            <input
              list="categories"
              placeholder="Pilih atau taip..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.category}
              onChange={e => setFormData({ ...formData, category: e.target.value })}
            />
            <datalist id="categories">
              {CATEGORIES.map(c => <option key={c} value={c} />)}
            </datalist>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Butiran</label>
            <input
              type="text"
              placeholder="Keterangan lanjut..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.details}
              onChange={e => setFormData({ ...formData, details: e.target.value })}
            />
          </div>

          <div className="pt-4 flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg font-medium hover:bg-gray-200 transition-colors"
            >
              Batal
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-slate-800 text-white rounded-lg font-medium hover:bg-slate-900 transition-colors shadow-lg"
            >
              {mode === 'edit' ? 'Kemaskini' : 'Simpan'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TransactionFormModal;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil 
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      // Create new (or copy)
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }

    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('copy');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-amber-500 p-2 rounded-lg text-slate-900">
                <Scale className="w-6 h-6" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 mr-2">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-md transition" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-md transition cursor-pointer border border-slate-600" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-md transition ml-2" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2 rounded-lg border border-indigo-100">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg p-2 font-bold cursor-pointer hover:bg-gray-100"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg p-2 font-bold cursor-pointer hover:bg-gray-100"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { 
                setEditingTransaction(null); 
                setModalMode('create');
                setIsAddModalOpen(true); 
              }}
              className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-6 py-2 rounded-lg shadow-md transition font-medium flex items-center justify-center gap-2"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-emerald-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.in)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-rose-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Keluar</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-indigo-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Baki (Mengikut Filter)</p>
              <p className={`text-2xl font-bold mt-1 ${totals.bal < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                {formatRM(totals.bal)}
              </p>
            </div>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Scale className="w-4 h-4 text-blue-500" /> Aliran Tunai (Keseluruhan Tahun {filterYear})
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData.barData}>
                    <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `RM${v/1000}k`} />
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Bar dataKey="Masuk" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="Keluar" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Table className="w-4 h-4 text-purple-500" /> Pecahan Belanja
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData.pieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.pieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Legend iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Ledger Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center bg-gray-50 gap-4">
              <h2 className="font-bold text-gray-800 flex items-center gap-2">
                <Table className="w-4 h-4 text-gray-500" /> Lejer Transaksi
              </h2>
              <div className="relative w-full sm:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, butiran..."
                  className="pl-10 w-full border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:ring-1 focus:ring-indigo-500 outline-none"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-gray-100 text-gray-600 uppercase text-xs font-bold">
                  <tr>
                    <th className="px-4 py-3">Tarikh</th>
                    <th className="px-4 py-3">Akaun</th>
                    <th className="px-4 py-3">Butiran</th>
                    <th className="px-4 py-3 text-right">Masuk</th>
                    <th className="px-4 py-3 text-right">Keluar</th>
                    <th className="px-4 py-3 text-center">Dokumen</th>
                    <th className="px-4 py-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-gray-500 text-xs font-mono">{formatDate(t.date)}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-1 rounded text-xs font-bold bg-indigo-50 text-indigo-700">{t.account}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-gray-800 text-sm">{t.name}</div>
                        <div className="text-xs text-gray-500">{t.details}</div>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-emerald-600">
                        {t.type === 'in' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-rose-600">
                        {t.type === 'out' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button 
                          onClick={() => printReceipt(t)}
                          className="text-xs border px-2 py-1 rounded bg-white hover:bg-gray-100 text-gray-600 transition-colors"
                        >
                          <Printer className="w-3 h-3 inline mr-1" /> Cetak
                        </button>
                      </td>
                      <td className="px-4 py-3 text-center flex justify-center gap-2">
                        <button onClick={() => handleEdit(t)} className="text-yellow-600 hover:text-yellow-800" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDuplicate(t)} className="text-blue-400 hover:text-blue-600" title="Salin">
                          <Copy className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteTransaction(t.id)} className="text-gray-300 hover:text-red-500" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredTransactions.length === 0 && (
                    <tr>
                      <td colSpan={7} className="py-12 text-center text-gray-500">Tiada rekod dijumpai.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      <TransactionFormModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        onSave={handleSaveTransaction}
        initialData={editingTransaction}
        mode={modalMode}
      />

      <InvoiceModal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        invoices={invoices}
        onAddInvoice={handleAddInvoice}
        onDeleteInvoice={handleDeleteInvoice}
        onPayInvoice={handlePayInvoice}
      />

      <ReportModal 
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
        transactions={transactions}
        year={filterYear}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, AlertCircle } from 'lucide-react';
import { ACCOUNTS, CATEGORIES, Transaction } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onSave: (t: Omit<Transaction, 'id'>) => void;
  initialData?: Transaction | null;
  mode?: 'create' | 'edit' | 'copy';
}

const TransactionFormModal: React.FC<Props> = ({ isOpen, onClose, onSave, initialData, mode = 'create' }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    account: ACCOUNTS[0],
    amount: '',
    name: '',
    category: '',
    details: ''
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [touched, setTouched] = useState<{ [key: string]: boolean }>({});

  useEffect(() => {
    if (initialData) {
      setFormData({
        date: initialData.date,
        type: initialData.type,
        account: initialData.account,
        amount: initialData.amount.toString(),
        name: initialData.name,
        category: initialData.category,
        details: initialData.details
      });
    } else {
      setFormData({
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: ACCOUNTS[0],
        amount: '',
        name: '',
        category: '',
        details: ''
      });
    }
    setErrors({});
    setTouched({});
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const validate = (data: typeof formData) => {
    const newErrors: { [key: string]: string } = {};

    if (!data.date) newErrors.date = "Tarikh diperlukan";
    if (!data.amount || isNaN(parseFloat(data.amount)) || parseFloat(data.amount) <= 0) {
      newErrors.amount = "Jumlah mesti lebih daripada 0";
    }
    if (!data.name.trim()) newErrors.name = "Nama diperlukan";

    return newErrors;
  };

  const handleChange = (field: keyof typeof formData, value: string) => {
    const newData = { ...formData, [field]: value };
    setFormData(newData);

    if (touched[field]) {
      const currentErrors = validate(newData);
      setErrors(prev => ({ ...prev, [field]: currentErrors[field] || '' }));
    }
  };

  const handleBlur = (field: keyof typeof formData) => {
    setTouched(prev => ({ ...prev, [field]: true }));
    const currentErrors = validate(formData);
    setErrors(prev => ({ ...prev, [field]: currentErrors[field] || '' }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const validationErrors = validate(formData);
    setErrors(validationErrors);
    setTouched({ date: true, amount: true, name: true });

    if (Object.keys(validationErrors).length === 0) {
      onSave({
        ...formData,
        amount: parseFloat(formData.amount) || 0
      });
      onClose();
    }
  };

  const getTitle = () => {
    if (mode === 'edit') return 'Kemaskini Rekod';
    if (mode === 'copy') return 'Salin Rekod';
    return 'Rekod Baru';
  };

  const getInputClass = (field: string) => 
    `w-full border rounded-lg p-2.5 text-sm outline-none focus:ring-2 transition-all ${
      errors[field] 
        ? 'border-rose-300 focus:border-rose-500 focus:ring-rose-200 bg-rose-50' 
        : 'border-gray-300 focus:border-indigo-500 focus:ring-indigo-500'
    }`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white w-full max-w-lg rounded-xl shadow-2xl overflow-y-auto max-h-[90vh] animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 py-4 border-b bg-gray-50 rounded-t-xl">
          <p className="text-lg font-bold text-gray-800">{getTitle()}</p>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Tarikh</label>
              <input
                type="date"
                className={getInputClass('date')}
                value={formData.date}
                onChange={e => handleChange('date', e.target.value)}
                onBlur={() => handleBlur('date')}
              />
              {errors.date && <p className="text-xs text-rose-600 mt-1 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/>{errors.date}</p>}
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Jenis</label>
              <select
                className={`w-full border border-gray-300 rounded-lg p-2.5 text-sm font-bold focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none ${formData.type === 'in' ? 'text-emerald-600' : 'text-rose-600'}`}
                value={formData.type}
                onChange={e => handleChange('type', e.target.value)}
              >
                <option value="in" className="text-emerald-600">Masuk (Income)</option>
                <option value="out" className="text-rose-600">Keluar (Expense)</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-indigo-600 uppercase mb-1">Akaun</label>
            <select
              className="w-full border border-gray-300 bg-indigo-50 rounded-lg p-2.5 text-sm font-bold text-indigo-900 focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.account}
              onChange={e => handleChange('account', e.target.value)}
            >
              {ACCOUNTS.map(acc => <option key={acc} value={acc}>{acc}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Jumlah (RM)</label>
            <input
              type="number"
              step="0.01"
              placeholder="0.00"
              className={`${getInputClass('amount')} font-mono font-bold text-lg`}
              value={formData.amount}
              onChange={e => handleChange('amount', e.target.value)}
              onBlur={() => handleBlur('amount')}
            />
            {errors.amount && <p className="text-xs text-rose-600 mt-1 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/>{errors.amount}</p>}
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nama Payer/Payee</label>
            <input
              type="text"
              placeholder="Nama..."
              className={getInputClass('name')}
              value={formData.name}
              onChange={e => handleChange('name', e.target.value)}
              onBlur={() => handleBlur('name')}
            />
            {errors.name && <p className="text-xs text-rose-600 mt-1 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/>{errors.name}</p>}
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Kategori</label>
            <input
              list="categories"
              placeholder="Pilih atau taip..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.category}
              onChange={e => handleChange('category', e.target.value)}
            />
            <datalist id="categories">
              {CATEGORIES.map(c => <option key={c} value={c} />)}
            </datalist>
          </div>

          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Butiran</label>
            <input
              type="text"
              placeholder="Keterangan lanjut..."
              className="w-full border border-gray-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
              value={formData.details}
              onChange={e => handleChange('details', e.target.value)}
            />
          </div>

          <div className="pt-4 flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg font-medium hover:bg-gray-200 transition-colors"
            >
              Batal
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-slate-800 text-white rounded-lg font-medium hover:bg-slate-900 transition-colors shadow-lg"
            >
              {mode === 'edit' ? 'Kemaskini' : 'Simpan'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TransactionFormModal;

import React, { useState } from 'react';
import { X, Printer, Trash2, Banknote, AlertCircle } from 'lucide-react';
import { Invoice } from '../types';
import { printInvoice, formatRM } from '../utils/printUtils';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  invoices: Invoice[];
  onAddInvoice: (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => void;
  onDeleteInvoice: (id: number) => void;
  onPayInvoice: (inv: Invoice) => void;
}

const InvoiceModal: React.FC<Props> = ({ isOpen, onClose, invoices, onAddInvoice, onDeleteInvoice, onPayInvoice }) => {
  const [formData, setFormData] = useState({
    no: '',
    client: '',
    desc: '',
    amount: ''
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [touched, setTouched] = useState<{ [key: string]: boolean }>({});

  if (!isOpen) return null;

  const validate = (data: typeof formData) => {
    const newErrors: { [key: string]: string } = {};
    if (!data.no.trim()) newErrors.no = "No. Invois diperlukan";
    if (!data.client.trim()) newErrors.client = "Nama Pelanggan diperlukan";
    if (!data.amount || isNaN(parseFloat(data.amount)) || parseFloat(data.amount) <= 0) {
      newErrors.amount = "Jumlah tidak sah";
    }
    return newErrors;
  };

  const handleChange = (field: keyof typeof formData, value: string) => {
    const newData = { ...formData, [field]: value };
    setFormData(newData);

    if (touched[field]) {
      const errs = validate(newData);
      setErrors(prev => ({ ...prev, [field]: errs[field] || '' }));
    }
  };

  const handleBlur = (field: keyof typeof formData) => {
    setTouched(prev => ({ ...prev, [field]: true }));
    const errs = validate(formData);
    setErrors(prev => ({ ...prev, [field]: errs[field] || '' }));
  };

  const handleSubmit = () => {
    const validationErrors = validate(formData);
    setErrors(validationErrors);
    setTouched({ no: true, client: true, amount: true, desc: true });

    if (Object.keys(validationErrors).length === 0) {
      onAddInvoice({
        no: formData.no,
        client: formData.client,
        desc: formData.desc,
        amount: parseFloat(formData.amount)
      });
      setFormData({ no: '', client: '', desc: '', amount: '' });
      setErrors({});
      setTouched({});
    }
  };

  const getInputClass = (field: string) => 
    `w-full border rounded-lg p-2 text-sm outline-none focus:ring-2 transition-all ${
      errors[field] 
        ? 'border-rose-300 focus:border-rose-500 focus:ring-rose-200 bg-rose-50' 
        : 'border-gray-300 focus:border-blue-500 focus:ring-blue-200'
    }`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/70 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-4xl h-[90vh] rounded-xl shadow-2xl flex flex-col animate-in fade-in zoom-in-95 duration-200">
        <div className="flex justify-between items-center px-6 py-4 border-b bg-blue-50 rounded-t-xl">
          <p className="text-lg font-bold text-blue-800 flex items-center gap-2">
            Pengurusan Invois
          </p>
          <button onClick={onClose} className="p-2 hover:bg-blue-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-blue-800" />
          </button>
        </div>

        <div className="flex-1 overflow-hidden p-6 flex flex-col md:flex-row gap-6">
          {/* Form */}
          <div className="w-full md:w-1/3 bg-gray-50 p-4 rounded-lg border border-gray-200 h-fit">
            <h3 className="font-bold text-gray-700 mb-3">Jana Invois Baru</h3>
            <div className="space-y-3">
              <div>
                <input 
                  placeholder="No. Invois (Cth: INV-2025-001)" 
                  className={getInputClass('no')}
                  value={formData.no}
                  onChange={e => handleChange('no', e.target.value)}
                  onBlur={() => handleBlur('no')}
                />
                {errors.no && <p className="text-xs text-rose-600 mt-1 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/>{errors.no}</p>}
              </div>

              <div>
                <input 
                  placeholder="Nama Pelanggan" 
                  className={getInputClass('client')}
                  value={formData.client}
                  onChange={e => handleChange('client', e.target.value)}
                  onBlur={() => handleBlur('client')}
                />
                {errors.client && <p className="text-xs text-rose-600 mt-1 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/>{errors.client}</p>}
              </div>

              <textarea 
                placeholder="Keterangan Caj..." 
                className="w-full border border-gray-300 rounded-lg p-2 text-sm h-20 resize-none focus:ring-2 focus:ring-blue-200 focus:border-blue-500 outline-none"
                value={formData.desc}
                onChange={e => handleChange('desc', e.target.value)}
              />

              <div>
                <input 
                  type="number" 
                  placeholder="Jumlah (RM)" 
                  className={`${getInputClass('amount')} font-mono`}
                  value={formData.amount}
                  onChange={e => handleChange('amount', e.target.value)}
                  onBlur={() => handleBlur('amount')}
                />
                {errors.amount && <p className="text-xs text-rose-600 mt-1 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/>{errors.amount}</p>}
              </div>

              <button onClick={handleSubmit} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 mt-2 transition-colors">
                Buat Invois
              </button>
            </div>
          </div>

          {/* List */}
          <div className="w-full md:w-2/3 flex flex-col">
            <h3 className="font-bold text-gray-700 mb-3">Senarai Invois</h3>
            <div className="flex-1 overflow-auto border rounded-lg bg-white">
              <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs sticky top-0">
                  <tr>
                    <th className="p-3">No. Invois</th>
                    <th className="p-3">Pelanggan</th>
                    <th className="p-3 text-right">Jumlah</th>
                    <th className="p-3 text-center">Status</th>
                    <th className="p-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {[...invoices].reverse().map(inv => (
                    <tr key={inv.id} className="hover:bg-gray-50">
                      <td className="p-3 font-mono text-xs font-bold text-gray-600">{inv.no}</td>
                      <td className="p-3">{inv.client}</td>
                      <td className="p-3 text-right font-bold">{formatRM(inv.amount)}</td>
                      <td className="p-3 text-center">
                        <span className={`px-2 py-1 rounded text-xs font-bold ${inv.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                          {inv.status === 'paid' ? 'DIBAYAR' : 'BELUM'}
                        </span>
                      </td>
                      <td className="p-3 flex justify-center gap-2">
                        <button onClick={() => printInvoice(inv)} className="text-blue-600 hover:text-blue-800" title="Cetak">
                          <Printer className="w-4 h-4" />
                        </button>
                        {inv.status === 'unpaid' && (
                          <button onClick={() => onPayInvoice(inv)} className="text-green-600 hover:text-green-800" title="Bayar">
                            <Banknote className="w-4 h-4" />
                          </button>
                        )}
                        <button onClick={() => onDeleteInvoice(inv.id)} className="text-red-400 hover:text-red-600" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {invoices.length === 0 && (
                    <tr>
                      <td colSpan={5} className="p-8 text-center text-gray-400">Tiada inbois direkodkan.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default InvoiceModal;

