};

export default TransactionFormModal;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil 
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      // Create new (or copy)
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }

    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('copy');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-amber-500 p-2 rounded-lg text-slate-900">
                <Scale className="w-6 h-6" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 mr-2">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-md transition" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-md transition cursor-pointer border border-slate-600" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-md transition ml-2" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2.5 rounded-xl border border-indigo-100 shadow-sm">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { 
                setEditingTransaction(null); 
                setModalMode('create');
                setIsAddModalOpen(true); 
              }}
              className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-6 py-2.5 rounded-xl shadow-lg transition font-medium flex items-center justify-center gap-2 transform active:scale-95"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-emerald-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.in)}</p>
