              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-indigo-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Baki (Mengikut Filter)</p>
              <p className={`text-2xl font-bold mt-1 ${totals.bal < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                {formatRM(totals.bal)}
              </p>
            </div>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Scale className="w-4 h-4 text-blue-500" /> Aliran Tunai (Keseluruhan Tahun {filterYear})
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData.barData}>
                    <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `RM${v/1000}k`} />
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Bar dataKey="Masuk" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="Keluar" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Table className="w-4 h-4 text-purple-500" /> Pecahan Belanja
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData.pieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.pieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Legend iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Ledger Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center bg-gray-50 gap-4">
              <h2 className="font-bold text-gray-800 flex items-center gap-2">
                <Table className="w-4 h-4 text-gray-500" /> Lejer Transaksi
              </h2>
              <div className="relative w-full sm:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, butiran..."
                  className="pl-10 w-full border border-gray-200 bg-gray-50 rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 outline-none focus:bg-white transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-gray-100 text-gray-600 uppercase text-xs font-bold">
                  <tr>
                    <th className="px-4 py-3">Tarikh</th>
                    <th className="px-4 py-3">Akaun</th>
                    <th className="px-4 py-3">Butiran</th>
                    <th className="px-4 py-3 text-right">Masuk</th>
                    <th className="px-4 py-3 text-right">Keluar</th>
                    <th className="px-4 py-3 text-center">Dokumen</th>
                    <th className="px-4 py-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-gray-500 text-xs font-mono">{formatDate(t.date)}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-1 rounded text-xs font-bold bg-indigo-50 text-indigo-700">{t.account}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-gray-800 text-sm">{t.name}</div>
                        <div className="text-xs text-gray-500">{t.details}</div>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-emerald-600">
                        {t.type === 'in' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-rose-600">
                        {t.type === 'out' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button 
                          onClick={() => printReceipt(t)}
                          className="text-xs border px-2 py-1 rounded-lg bg-white hover:bg-gray-100 text-gray-600 transition-colors"
                        >
                          <Printer className="w-3 h-3 inline mr-1" /> Cetak
                        </button>
                      </td>
                      <td className="px-4 py-3 text-center flex justify-center gap-2">
                        <button onClick={() => handleEdit(t)} className="p-1.5 bg-yellow-50 text-yellow-600 rounded-xl hover:bg-yellow-100 hover:text-yellow-700 transition-colors" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDuplicate(t)} className="p-1.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 hover:text-blue-700 transition-colors" title="Salin">
                          <Copy className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteTransaction(t.id)} className="p-1.5 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 hover:text-red-600 transition-colors" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredTransactions.length === 0 && (
                    <tr>
                      <td colSpan={7} className="py-12 text-center text-gray-500">Tiada rekod dijumpai.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      <TransactionFormModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        onSave={handleSaveTransaction}
        initialData={editingTransaction}
        mode={modalMode}
      />

      <InvoiceModal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        invoices={invoices}
        onAddInvoice={handleAddInvoice}
        onDeleteInvoice={handleDeleteInvoice}
        onPayInvoice={handlePayInvoice}
      />

      <ReportModal 
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
        transactions={transactions}
        year={filterYear}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, AlertCircle, Calendar, Wallet, User, Tag, FileText, ArrowUpCircle, ArrowDownCircle, Check, DollarSign } from 'lucide-react';
import { ACCOUNTS, CATEGORIES, Transaction } from '../types';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onSave: (t: Omit<Transaction, 'id'>) => void;
  initialData?: Transaction | null;
  mode?: 'create' | 'edit' | 'copy';
}

const TransactionFormModal: React.FC<Props> = ({ isOpen, onClose, onSave, initialData, mode = 'create' }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    account: ACCOUNTS[0],
    amount: '',
    name: '',
    category: '',
    details: ''
  });

  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [touched, setTouched] = useState<{ [key: string]: boolean }>({});

  useEffect(() => {
    if (initialData) {
      setFormData({
        date: initialData.date,
        type: initialData.type,
        account: initialData.account,
        amount: initialData.amount.toString(),
        name: initialData.name,
        category: initialData.category,
        details: initialData.details
      });
    } else {
      setFormData({
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: ACCOUNTS[0],
        amount: '',
        name: '',
        category: '',
        details: ''
      });
    }
    setErrors({});
    setTouched({});
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const validate = (data: typeof formData) => {
    const newErrors: { [key: string]: string } = {};
    if (!data.date) newErrors.date = "Tarikh diperlukan";
    if (!data.amount || isNaN(parseFloat(data.amount)) || parseFloat(data.amount) <= 0) {
      newErrors.amount = "Jumlah mesti lebih daripada 0";
    }
    if (!data.name.trim()) newErrors.name = "Nama diperlukan";
    return newErrors;
  };

  const handleChange = (field: keyof typeof formData, value: string) => {
    const newData = { ...formData, [field]: value };
    setFormData(newData);
    if (touched[field as string]) {
      const currentErrors = validate(newData);
      setErrors(prev => ({ ...prev, [field as string]: currentErrors[field as string] || '' }));
    }
  };

  const handleBlur = (field: keyof typeof formData) => {
    setTouched(prev => ({ ...prev, [field as string]: true }));
    const currentErrors = validate(formData);
    setErrors(prev => ({ ...prev, [field as string]: currentErrors[field as string] || '' }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const validationErrors = validate(formData);
    setErrors(validationErrors);
    setTouched({ date: true, amount: true, name: true });

    if (Object.keys(validationErrors).length === 0) {
      onSave({
        ...formData,
        amount: parseFloat(formData.amount) || 0
      });
      onClose();
    }
  };

  const getTitle = () => {
    if (mode === 'edit') return 'Kemaskini Transaksi';
    if (mode === 'copy') return 'Salin Transaksi';
    return 'Rekod Transaksi';
  };

  const isIncome = formData.type === 'in';

  // Theme Configuration
  const theme = isIncome ? {
      gradient: 'from-emerald-600 to-emerald-500',
      lightBg: 'bg-emerald-50',
      darkText: 'text-emerald-700',
      iconBg: 'bg-emerald-100',
      iconText: 'text-emerald-600',
      focusRing: 'focus:ring-emerald-100',
      focusBorder: 'focus:border-emerald-500',
      btn: 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 focus:ring-emerald-200',
      pillActive: 'bg-emerald-100 border-emerald-200 text-emerald-700'
  } : {
      gradient: 'from-rose-600 to-rose-500',
      lightBg: 'bg-rose-50',
      darkText: 'text-rose-700',
      iconBg: 'bg-rose-100',
      iconText: 'text-rose-600',
      focusRing: 'focus:ring-rose-100',
      focusBorder: 'focus:border-rose-500',
      btn: 'bg-rose-600 hover:bg-rose-700 shadow-rose-200 focus:ring-rose-200',
      pillActive: 'bg-rose-100 border-rose-200 text-rose-700'
  };

  // Common categories for quick selection
  const commonCategories = isIncome 
    ? ["Legal Fee", "Retainer", "Consultation", "Reimbursement"]
    : ["Filing Fee", "Office Supplies", "Utilities", "Mileage", "Salary", "Rental", "Printing", "Refreshments"];

  const inputBaseClass = "w-full border rounded-xl p-2.5 text-sm outline-none transition-all pl-10";
  const getInputClass = (field: string) => 
    `${inputBaseClass} ${
      errors[field] 
        ? 'border-rose-300 focus:border-rose-500 focus:ring-2 focus:ring-rose-200 bg-rose-50' 
        : `border-gray-200 ${theme.focusBorder} focus:ring-2 ${theme.focusRing} bg-gray-50 focus:bg-white text-gray-700`
    }`;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" onClick={onClose} />
      <div className="relative bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className={`px-6 py-5 border-b flex justify-between items-center bg-gradient-to-r transition-all duration-300 ${theme.gradient}`}>
          <div className="flex items-center gap-3 text-white">
            <div className="p-2 bg-white/20 rounded-xl backdrop-blur-sm shadow-sm">
              {isIncome ? <ArrowUpCircle className="w-6 h-6" /> : <ArrowDownCircle className="w-6 h-6" />}
            </div>
            <div>
              <p className="text-lg font-bold leading-tight">{getTitle()}</p>
              <p className="text-xs text-white/90 font-medium uppercase tracking-wider opacity-90">{isIncome ? 'Terimaan Wang (Income)' : 'Perbelanjaan (Expense)'}</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-full transition-colors text-white">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-gray-200">
          <form onSubmit={handleSubmit} className="space-y-6">

            {/* Type Toggle */}
            <div className="flex p-1 rounded-xl bg-gray-100 border border-gray-200">
              <button
                type="button"
                onClick={() => handleChange('type', 'in')}
                className={`flex-1 py-2 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all duration-200 ${isIncome ? 'bg-white text-emerald-600 shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200/50'}`}
              >
                <ArrowUpCircle className="w-4 h-4" /> Masuk
              </button>
              <button
                type="button"
                onClick={() => handleChange('type', 'out')}
                className={`flex-1 py-2 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all duration-200 ${!isIncome ? 'bg-white text-rose-600 shadow-sm ring-1 ring-black/5' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200/50'}`}
              >
                <ArrowDownCircle className="w-4 h-4" /> Keluar
              </button>
            </div>

            {/* Amount - Hero Input */}
            <div className="relative group">
              <label className={`block text-xs font-bold uppercase mb-2 ml-1 ${theme.darkText}`}>
                Jumlah Transaksi (RM)
              </label>
              <div className="relative">
                <div className={`absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none p-1.5 rounded-lg ${theme.iconBg} ${theme.iconText}`}>
                    <DollarSign className="w-5 h-5" strokeWidth={3} />
                </div>
                <input
                  type="number"
                  step="0.01"
                  placeholder="0.00"
                  className={`w-full border rounded-xl p-4 pl-14 text-3xl font-bold outline-none transition-all placeholder-gray-300 ${
                    errors.amount 
                      ? 'border-rose-300 bg-rose-50 text-rose-800 focus:ring-4 focus:ring-rose-200' 
                      : `border-gray-200 text-gray-800 ${theme.focusBorder} focus:ring-4 ${theme.focusRing} bg-white`
                  }`}
                  value={formData.amount}
                  onChange={e => handleChange('amount', e.target.value)}
                  onBlur={() => handleBlur('amount')}
                />
              </div>
              {errors.amount && <p className="text-xs text-rose-600 mt-1 flex items-center font-medium px-1 animate-in slide-in-from-left-1"><AlertCircle className="w-3 h-3 mr-1"/>{errors.amount}</p>}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              {/* Date */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-gray-500 uppercase ml-1">Tarikh</label>
                <div className="relative group">
                  <Calendar className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 group-hover:text-gray-600 transition-colors" />
                  <input
                    type="date"
                    className={getInputClass('date')}
                    value={formData.date}
                    onChange={e => handleChange('date', e.target.value)}
                    onBlur={() => handleBlur('date')}
                  />
                </div>
                {errors.date && <p className="text-xs text-rose-600 flex items-center px-1"><AlertCircle className="w-3 h-3 mr-1"/>{errors.date}</p>}
              </div>

              {/* Account */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-gray-500 uppercase ml-1">Akaun</label>
                <div className="relative group">
                  <Wallet className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 group-hover:text-gray-600 transition-colors" />
                  <select
                    className={`w-full border rounded-xl p-2.5 pl-10 text-sm font-medium outline-none appearance-none cursor-pointer transition-all ${
                        `border-gray-200 bg-gray-50 focus:bg-white ${theme.focusBorder} focus:ring-2 ${theme.focusRing} text-gray-700`
                    }`}
                    value={formData.account}
                    onChange={e => handleChange('account', e.target.value)}
                  >
                    {ACCOUNTS.map(acc => <option key={acc} value={acc}>{acc}</option>)}
                  </select>
                  <div className="absolute right-3 top-3 pointer-events-none">
                    <ArrowDownCircle className="w-3 h-3 text-gray-400" />
                  </div>
                </div>
              </div>
            </div>

            {/* Name */}
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-gray-500 uppercase ml-1">Nama (Payer / Payee)</label>
              <div className="relative group">
                <User className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 group-hover:text-gray-600 transition-colors" />
                <input
                  type="text"
                  placeholder="Contoh: Ali Bin Abu / TNB"
                  className={getInputClass('name')}
                  value={formData.name}
                  onChange={e => handleChange('name', e.target.value)}
                  onBlur={() => handleBlur('name')}
                />
              </div>
              {errors.name && <p className="text-xs text-rose-600 flex items-center px-1"><AlertCircle className="w-3 h-3 mr-1"/>{errors.name}</p>}
            </div>

            {/* Category */}
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-gray-500 uppercase ml-1">Kategori</label>
              <div className="relative group">
                <Tag className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 group-hover:text-gray-600 transition-colors" />
                <input
                  list="categories"
                  placeholder="Pilih atau taip kategori..."
                  className={getInputClass('category')}
                  value={formData.category}
                  onChange={e => handleChange('category', e.target.value)}
                />
                <datalist id="categories">
                  {CATEGORIES.map(c => <option key={c} value={c} />)}
                </datalist>
              </div>

              {/* Quick Category Pills */}
              <div className="flex flex-wrap gap-2 mt-2 px-1">
                  {commonCategories.map(cat => (
                    <button
                      key={cat}
                      type="button"
                      onClick={() => handleChange('category', cat)}
                      className={`text-[10px] uppercase font-bold px-2.5 py-1 rounded-full border transition-all active:scale-95 ${
                        formData.category === cat 
                          ? `${theme.pillActive} shadow-sm`
                          : 'bg-white border-gray-200 text-gray-500 hover:border-gray-300 hover:text-gray-700'
                      }`}
                    >
                      {cat}
                    </button>
                  ))}
              </div>
            </div>

            {/* Details */}
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-gray-500 uppercase ml-1">Butiran / Keterangan</label>
              <div className="relative group">
                <FileText className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 group-hover:text-gray-600 transition-colors" />
                <input
                  type="text"
                  placeholder="Nota tambahan (pilihan)..."
                  className={getInputClass('details')}
                  value={formData.details}
                  onChange={e => handleChange('details', e.target.value)}
                />
              </div>
            </div>

          </form>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 flex justify-end gap-3 z-10">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 bg-white border border-gray-300 text-gray-700 rounded-xl font-bold text-sm hover:bg-gray-50 hover:border-gray-400 transition-colors focus:ring-2 focus:ring-gray-200"
          >
            Batal
          </button>
          <button
            onClick={handleSubmit}
            type="submit"
            className={`px-6 py-2.5 rounded-xl font-bold text-sm text-white shadow-lg flex items-center gap-2 transition-transform active:scale-95 focus:ring-4 focus:ring-opacity-50 ${theme.btn}`}
          >
            <Check className="w-4 h-4" /> {mode === 'edit' ? 'Kemaskini' : 'Simpan Rekod'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionFormModal;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil 
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      // Create new (or copy)
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }

    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('copy');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-amber-500 p-2 rounded-lg text-slate-900">
                <Scale className="w-6 h-6" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 mr-2">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-md transition" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-md transition cursor-pointer border border-slate-600" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-md transition ml-2" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2.5 rounded-xl border border-indigo-100 shadow-sm">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { 
                setEditingTransaction(null); 
                setModalMode('create');
                setIsAddModalOpen(true); 
              }}
              className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-6 py-2.5 rounded-xl shadow-lg transition font-medium flex items-center justify-center gap-2 transform active:scale-95"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-emerald-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.in)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-rose-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Keluar</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-indigo-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Baki (Mengikut Filter)</p>
              <p className={`text-2xl font-bold mt-1 ${totals.bal < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                {formatRM(totals.bal)}
              </p>
            </div>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Scale className="w-4 h-4 text-blue-500" /> Aliran Tunai (Keseluruhan Tahun {filterYear})
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData.barData}>
                    <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `RM${v/1000}k`} />
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Bar dataKey="Masuk" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="Keluar" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Table className="w-4 h-4 text-purple-500" /> Pecahan Belanja
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData.pieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.pieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Legend iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Ledger Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center bg-gray-50 gap-4">
              <h2 className="font-bold text-gray-800 flex items-center gap-2">
                <Table className="w-4 h-4 text-gray-500" /> Lejer Transaksi
              </h2>
              <div className="relative w-full sm:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, butiran..."
                  className="pl-10 w-full border border-gray-200 bg-gray-50 rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 outline-none focus:bg-white transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-gray-100 text-gray-600 uppercase text-xs font-bold">
                  <tr>
                    <th className="px-4 py-3">Tarikh</th>
                    <th className="px-4 py-3">Akaun</th>
                    <th className="px-4 py-3">Butiran</th>
                    <th className="px-4 py-3 text-right">Masuk</th>
                    <th className="px-4 py-3 text-right">Keluar</th>
                    <th className="px-4 py-3 text-center">Dokumen</th>
                    <th className="px-4 py-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-gray-500 text-xs font-mono">{formatDate(t.date)}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-1 rounded text-xs font-bold bg-indigo-50 text-indigo-700">{t.account}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-gray-800 text-sm">{t.name}</div>
                        <div className="text-xs text-gray-500">{t.details}</div>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-emerald-600">
                        {t.type === 'in' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-rose-600">
                        {t.type === 'out' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button 
                          onClick={() => printReceipt(t)}
                          className="text-xs border px-2 py-1 rounded-lg bg-white hover:bg-gray-100 text-gray-600 transition-colors"
                        >
                          <Printer className="w-3 h-3 inline mr-1" /> Cetak
                        </button>
                      </td>
                      <td className="px-4 py-3 text-center flex justify-center gap-2">
                        <button onClick={() => handleEdit(t)} className="p-1.5 bg-yellow-50 text-yellow-600 rounded-xl hover:bg-yellow-100 hover:text-yellow-700 transition-colors" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDuplicate(t)} className="p-1.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 hover:text-blue-700 transition-colors" title="Salin">
                          <Copy className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteTransaction(t.id)} className="p-1.5 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 hover:text-red-600 transition-colors" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredTransactions.length === 0 && (
                    <tr>
                      <td colSpan={7} className="py-12 text-center text-gray-500">Tiada rekod dijumpai.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      <TransactionFormModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        onSave={handleSaveTransaction}
        initialData={editingTransaction}
        mode={modalMode}
      />

      <InvoiceModal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        invoices={invoices}
        onAddInvoice={handleAddInvoice}
        onDeleteInvoice={handleDeleteInvoice}
        onPayInvoice={handlePayInvoice}
      />

      <ReportModal 
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
        transactions={transactions}
        year={filterYear}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil, Lock, LogOut
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- Auth State ---
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return sessionStorage.getItem('hma_auth') === 'true';
  });
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState('');

  // --- Data State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === '025495') {
      setIsAuthenticated(true);
      sessionStorage.setItem('hma_auth', 'true');
      setLoginError('');
      setPasswordInput('');
    } else {
      setLoginError('Kata laluan tidak sah.');
      setPasswordInput('');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('hma_auth');
  };

  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      // Create new (or copy)
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }

    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('copy');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  // --- Auth View ---
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md animate-in fade-in zoom-in-95 duration-300">
          <div className="flex flex-col items-center mb-6">
            <div className="bg-slate-900 p-4 rounded-full shadow-lg mb-4">
              <Lock className="w-8 h-8 text-amber-500" />
            </div>
            <h1 className="text-2xl font-bold text-gray-800 tracking-tight">Akses Sistem</h1>
            <p className="text-sm text-gray-500">Hairi Mustafa Associates</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <input
                type="password"
                placeholder="Masukkan kata laluan..."
                className={`w-full border rounded-xl px-4 py-3 text-center text-lg tracking-widest outline-none focus:ring-2 transition-all ${
                  loginError 
                    ? 'border-rose-300 bg-rose-50 focus:ring-rose-200' 
                    : 'border-gray-200 bg-gray-50 focus:bg-white focus:border-indigo-500 focus:ring-indigo-100'
                }`}
                value={passwordInput}
                onChange={(e) => {
                  setPasswordInput(e.target.value);
                  setLoginError('');
                }}
                autoFocus
              />
              {loginError && (
                <p className="text-center text-rose-600 text-sm mt-2 font-medium flex items-center justify-center gap-1">
                  <AlertCircle className="w-3 h-3" /> {loginError}
                </p>
              )}
            </div>
            <button 
              type="submit" 
              className="w-full bg-slate-900 hover:bg-slate-800 text-white py-3 rounded-xl font-bold transition-all shadow-lg active:scale-95"
            >
              Masuk
            </button>
          </form>

          <div className="mt-8 text-center text-xs text-gray-400">
            &copy; {new Date().getFullYear()} HMA Management System
          </div>
        </div>
      </div>
    );
  }

  // --- Main View ---
  return (
    <div className="flex flex-col h-screen bg-slate-50">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-amber-500 p-2 rounded-lg text-slate-900">
                <Scale className="w-6 h-6" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 mr-2">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-md transition" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-md transition cursor-pointer border border-slate-600" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-md transition ml-2" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
              <button onClick={handleLogout} className="bg-slate-800 hover:bg-slate-700 text-gray-300 hover:text-white px-3 py-2 rounded-md transition ml-2 border border-slate-700" title="Log Keluar">
                <LogOut className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2.5 rounded-xl border border-indigo-100 shadow-sm">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { 
                setEditingTransaction(null); 
                setModalMode('create');
                setIsAddModalOpen(true); 
              }}
              className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-6 py-2.5 rounded-xl shadow-lg transition font-medium flex items-center justify-center gap-2 transform active:scale-95"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-emerald-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.in)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-rose-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Keluar</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-indigo-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Baki (Mengikut Filter)</p>
              <p className={`text-2xl font-bold mt-1 ${totals.bal < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                {formatRM(totals.bal)}
              </p>
            </div>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Scale className="w-4 h-4 text-blue-500" /> Aliran Tunai (Keseluruhan Tahun {filterYear})
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData.barData}>
                    <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `RM${v/1000}k`} />
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Bar dataKey="Masuk" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="Keluar" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Table className="w-4 h-4 text-purple-500" /> Pecahan Belanja
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData.pieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.pieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Legend iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Ledger Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center bg-gray-50 gap-4">
              <h2 className="font-bold text-gray-800 flex items-center gap-2">
                <Table className="w-4 h-4 text-gray-500" /> Lejer Transaksi
              </h2>
              <div className="relative w-full sm:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, butiran..."
                  className="pl-10 w-full border border-gray-200 bg-gray-50 rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 outline-none focus:bg-white transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-gray-100 text-gray-600 uppercase text-xs font-bold">
                  <tr>
                    <th className="px-4 py-3">Tarikh</th>
                    <th className="px-4 py-3">Akaun</th>
                    <th className="px-4 py-3">Butiran</th>
                    <th className="px-4 py-3 text-right">Masuk</th>
                    <th className="px-4 py-3 text-right">Keluar</th>
                    <th className="px-4 py-3 text-center">Dokumen</th>
                    <th className="px-4 py-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-gray-500 text-xs font-mono">{formatDate(t.date)}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-1 rounded text-xs font-bold bg-indigo-50 text-indigo-700">{t.account}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-gray-800 text-sm">{t.name}</div>
                        <div className="text-xs text-gray-500">{t.details}</div>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-emerald-600">
                        {t.type === 'in' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-rose-600">
                        {t.type === 'out' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button 
                          onClick={() => printReceipt(t)}
                          className="text-xs border px-2 py-1 rounded-lg bg-white hover:bg-gray-100 text-gray-600 transition-colors"
                        >
                          <Printer className="w-3 h-3 inline mr-1" /> Cetak
                        </button>
                      </td>
                      <td className="px-4 py-3 text-center flex justify-center gap-2">
                        <button onClick={() => handleEdit(t)} className="p-1.5 bg-yellow-50 text-yellow-600 rounded-xl hover:bg-yellow-100 hover:text-yellow-700 transition-colors" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDuplicate(t)} className="p-1.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 hover:text-blue-700 transition-colors" title="Salin">
                          <Copy className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteTransaction(t.id)} className="p-1.5 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 hover:text-red-600 transition-colors" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredTransactions.length === 0 && (
                    <tr>
                      <td colSpan={7} className="py-12 text-center text-gray-500">Tiada rekod dijumpai.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      <TransactionFormModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        onSave={handleSaveTransaction}
        initialData={editingTransaction}
        mode={modalMode}
      />

      <InvoiceModal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        invoices={invoices}
        onAddInvoice={handleAddInvoice}
        onDeleteInvoice={handleDeleteInvoice}
        onPayInvoice={handlePayInvoice}
      />

      <ReportModal 
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
        transactions={transactions}
        year={filterYear}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil, Lock, LogOut
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- Auth State ---
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return sessionStorage.getItem('hma_auth') === 'true';
  });
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState('');

  // --- Data State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === '025495') {
      setIsAuthenticated(true);
      sessionStorage.setItem('hma_auth', 'true');
      setLoginError('');
      setPasswordInput('');
    } else {
      setLoginError('Kata laluan tidak sah.');
      setPasswordInput('');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('hma_auth');
  };

  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      // Create new (or copy)
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }

    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('copy');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  // --- Auth View ---
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-gray-900 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-in fade-in zoom-in-95 duration-500">
          <div className="flex flex-col items-center mb-8">
            <div className="bg-gradient-to-tr from-amber-400 to-amber-600 p-4 rounded-full shadow-lg mb-4 ring-4 ring-amber-100">
              <Lock className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-2xl font-bold text-gray-800 tracking-tight">Akses Sistem</h1>
            <p className="text-sm text-gray-500 font-medium">Hairi Mustafa Associates</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <input
                type="password"
                placeholder="Kata Laluan"
                className={`w-full border rounded-xl px-4 py-3.5 text-center text-lg tracking-widest outline-none transition-all duration-200 shadow-sm ${
                  loginError 
                    ? 'border-rose-300 bg-rose-50 focus:ring-4 focus:ring-rose-100' 
                    : 'border-gray-200 bg-gray-50 focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100'
                }`}
                value={passwordInput}
                onChange={(e) => {
                  setPasswordInput(e.target.value);
                  setLoginError('');
                }}
                autoFocus
              />
              {loginError && (
                <p className="text-center text-rose-600 text-sm mt-2 font-bold flex items-center justify-center gap-1 animate-pulse">
                  <AlertCircle className="w-4 h-4" /> {loginError}
                </p>
              )}
            </div>
            <button 
              type="submit" 
              className="w-full bg-slate-900 hover:bg-slate-800 text-white py-3.5 rounded-xl font-bold transition-all shadow-lg hover:shadow-xl active:scale-95 transform"
            >
              Masuk
            </button>
          </form>

          <div className="mt-8 text-center text-xs text-gray-400 font-medium">
            &copy; {new Date().getFullYear()} HMA Management System
          </div>
        </div>
      </div>
    );
  }

  // --- Main View ---
  return (
    <div className="flex flex-col h-screen bg-gray-100">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-tr from-amber-400 to-amber-600 p-2 rounded-lg text-slate-900 shadow-md">
                <Scale className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 shadow-sm">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-md text-sm font-medium transition flex items-center gap-2 mr-2 shadow-sm">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-md transition shadow-sm" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-md transition cursor-pointer border border-slate-600 shadow-sm" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-md transition ml-2 shadow-sm" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
              <button onClick={handleLogout} className="bg-slate-800 hover:bg-slate-700 text-gray-300 hover:text-white px-3 py-2 rounded-md transition ml-2 border border-slate-700 shadow-sm" title="Log Keluar">
                <LogOut className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2.5 rounded-xl border border-indigo-100 shadow-sm">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none shadow-sm"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-900 text-sm rounded-xl p-2.5 font-bold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none shadow-sm"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { 
                setEditingTransaction(null); 
                setModalMode('create');
                setIsAddModalOpen(true); 
              }}
              className="w-full md:w-auto bg-slate-800 hover:bg-slate-900 text-white px-6 py-2.5 rounded-xl shadow-lg transition font-medium flex items-center justify-center gap-2 transform active:scale-95"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-emerald-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.in)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-rose-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Jumlah Keluar</p>
              <p className="text-2xl font-bold text-gray-800 mt-1">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border-l-4 border-indigo-500">
              <p className="text-xs font-bold text-gray-400 uppercase">Baki (Mengikut Filter)</p>
              <p className={`text-2xl font-bold mt-1 ${totals.bal < 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                {formatRM(totals.bal)}
              </p>
            </div>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Scale className="w-4 h-4 text-blue-500" /> Aliran Tunai (Keseluruhan Tahun {filterYear})
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData.barData}>
                    <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                    <YAxis fontSize={12} tickLine={false} axisLine={false} tickFormatter={(v) => `RM${v/1000}k`} />
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Bar dataKey="Masuk" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="Keluar" fill="#f43f5e" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
              <h3 className="text-sm font-bold text-gray-700 mb-4 flex items-center gap-2">
                <Table className="w-4 h-4 text-purple-500" /> Pecahan Belanja
              </h3>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData.pieData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.pieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <RechartsTooltip formatter={(value: number) => formatRM(value)} />
                    <Legend iconSize={8} wrapperStyle={{ fontSize: '10px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Ledger Table */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center bg-gray-50 gap-4">
              <h2 className="font-bold text-gray-800 flex items-center gap-2">
                <Table className="w-4 h-4 text-gray-500" /> Lejer Transaksi
              </h2>
              <div className="relative w-full sm:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="text"
                  placeholder="Cari nama, butiran..."
                  className="pl-10 w-full border border-gray-200 bg-gray-50 rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 outline-none focus:bg-white transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm whitespace-nowrap">
                <thead className="bg-gray-100 text-gray-600 uppercase text-xs font-bold">
                  <tr>
                    <th className="px-4 py-3">Tarikh</th>
                    <th className="px-4 py-3">Akaun</th>
                    <th className="px-4 py-3">Butiran</th>
                    <th className="px-4 py-3 text-right">Masuk</th>
                    <th className="px-4 py-3 text-right">Keluar</th>
                    <th className="px-4 py-3 text-center">Dokumen</th>
                    <th className="px-4 py-3 text-center">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50">
                      <td className="px-4 py-3 text-gray-500 text-xs font-mono">{formatDate(t.date)}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-1 rounded text-xs font-bold bg-indigo-50 text-indigo-700">{t.account}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="font-bold text-gray-800 text-sm">{t.name}</div>
                        <div className="text-xs text-gray-500">{t.details}</div>
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-emerald-600">
                        {t.type === 'in' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-right font-bold text-rose-600">
                        {t.type === 'out' ? formatRM(t.amount) : ''}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button 
                          onClick={() => printReceipt(t)}
                          className="text-xs border px-2 py-1 rounded-lg bg-white hover:bg-gray-100 text-gray-600 transition-colors"
                        >
                          <Printer className="w-3 h-3 inline mr-1" /> Cetak
                        </button>
                      </td>
                      <td className="px-4 py-3 text-center flex justify-center gap-2">
                        <button onClick={() => handleEdit(t)} className="p-1.5 bg-yellow-50 text-yellow-600 rounded-xl hover:bg-yellow-100 hover:text-yellow-700 transition-colors" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDuplicate(t)} className="p-1.5 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 hover:text-blue-700 transition-colors" title="Salin">
                          <Copy className="w-4 h-4" />
                        </button>
                        <button onClick={() => handleDeleteTransaction(t.id)} className="p-1.5 bg-red-50 text-red-500 rounded-xl hover:bg-red-100 hover:text-red-600 transition-colors" title="Padam">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredTransactions.length === 0 && (
                    <tr>
                      <td colSpan={7} className="py-12 text-center text-gray-500">Tiada rekod dijumpai.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {/* Modals */}
      <TransactionFormModal 
        isOpen={isAddModalOpen} 
        onClose={() => setIsAddModalOpen(false)}
        onSave={handleSaveTransaction}
        initialData={editingTransaction}
        mode={modalMode}
      />

      <InvoiceModal
        isOpen={isInvoiceModalOpen}
        onClose={() => setIsInvoiceModalOpen(false)}
        invoices={invoices}
        onAddInvoice={handleAddInvoice}
        onDeleteInvoice={handleDeleteInvoice}
        onPayInvoice={handlePayInvoice}
      />

      <ReportModal 
        isOpen={isReportModalOpen}
        onClose={() => setIsReportModalOpen(false)}
        transactions={transactions}
        year={filterYear}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil, Lock, LogOut
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';

const App: React.FC = () => {
  // --- Auth State ---
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return sessionStorage.getItem('hma_auth') === 'true';
  });
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState('');

  // --- Data State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  // Data for editing (Copy function)
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Backup Warning State
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    // 7 days in ms
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  const chartData = useMemo(() => {
    const mIn = Array(12).fill(0);
    const mOut = Array(12).fill(0);
    const categoryData: Record<string, number> = {};

    transactions.forEach(t => {
      const d = new Date(t.date);
      // Chart data respects Account filter but shows WHOLE YEAR for context
      if (d.getFullYear() === filterYear && (filterAccount === 'all' || t.account === filterAccount)) {
        const m = d.getMonth();
        if (t.type === 'in') {
          mIn[m] += t.amount;
        } else {
          mOut[m] += t.amount;
          categoryData[t.category] = (categoryData[t.category] || 0) + t.amount;
        }
      }
    });

    const barData = MONTHS.map((m, i) => ({
      name: m.substring(0, 3),
      Masuk: mIn[i],
      Keluar: mOut[i]
    }));

    const pieData = Object.keys(categoryData).map(key => ({
      name: key,
      value: categoryData[key]
    }));

    return { barData, pieData };
  }, [transactions, filterYear, filterAccount]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === '025495') {
      setIsAuthenticated(true);
      sessionStorage.setItem('hma_auth', 'true');
      setLoginError('');
      setPasswordInput('');
    } else {
      setLoginError('Kata laluan tidak sah.');
      setPasswordInput('');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('hma_auth');
  };

  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      // Update existing
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      // Create new (or copy)
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }

    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleDuplicate = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('copy');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      // Update invoice
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));

      // Add transaction
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat', // Default
        amount: inv.amount,
        name: inv.client,
        category: 'Legal Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    let csv = "data:text/csv;charset=utf-8,Tarikh,Akaun,Jenis,Nama,Butiran,Jumlah\n";
    transactions.forEach(t => {
      csv += `${t.date},${t.account},${t.type},${t.name},${t.details},${t.amount}\n`;
    });

    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `HMA_Backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      const lines = content.split('\n');
      const newTrans: Transaction[] = [];

      // Skip header i=1
      for (let i = 1; i < lines.length; i++) {
        const c = lines[i].split(',');
        if (c.length < 6) continue;
        newTrans.push({
          id: Date.now() + Math.random(),
          date: c[0],
          account: c[1],
          type: c[2] as 'in' | 'out',
          name: c[3],
          details: c[4],
          amount: parseFloat(c[5]),
          category: 'Import'
        });
      }
      setTransactions(prev => [...prev, ...newTrans]);
      alert("Data berjaya diimport!");
    };
    reader.readAsText(file);
    // Reset input
    e.target.value = ''; 
  };

  const handleReset = () => {
    if (confirm("AMARAN: Ini akan memadam SEMUA data. Teruskan?")) {
      setTransactions([]);
      setInvoices([]);
      localStorage.removeItem('hma_db_trans');
      localStorage.removeItem('hma_db_invoices');
    }
  };

  const PIE_COLORS = ['#6366f1', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#8b5cf6'];

  // --- Auth View ---
  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-gray-900 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-2xl shadow-2xl w-full max-w-md animate-in fade-in zoom-in-95 duration-500 border border-white/10">
          <div className="flex flex-col items-center mb-8">
            <div className="bg-gradient-to-tr from-amber-400 to-amber-600 p-4 rounded-full shadow-lg mb-4 ring-4 ring-amber-100">
              <Lock className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-2xl font-bold text-gray-800 tracking-tight">Akses Sistem</h1>
            <p className="text-sm text-gray-500 font-medium">Hairi Mustafa Associates</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <input
                type="password"
                placeholder="Kata Laluan"
                className={`w-full border rounded-xl px-4 py-3.5 text-center text-lg tracking-widest outline-none transition-all duration-200 shadow-sm ${
                  loginError 
                    ? 'border-rose-300 bg-rose-50 focus:ring-4 focus:ring-rose-100' 
                    : 'border-gray-200 bg-gray-50 focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100 text-gray-800'
                }`}
                value={passwordInput}
                onChange={(e) => {
                  setPasswordInput(e.target.value);
                  setLoginError('');
                }}
                autoFocus
              />
              {loginError && (
                <p className="text-center text-rose-600 text-sm mt-2 font-bold flex items-center justify-center gap-1 animate-pulse">
                  <AlertCircle className="w-4 h-4" /> {loginError}
                </p>
              )}
            </div>
            <button 
              type="submit" 
              className="w-full bg-slate-900 hover:bg-slate-800 text-white py-3.5 rounded-xl font-bold transition-all shadow-lg hover:shadow-xl active:scale-95 transform"
            >
              Masuk
            </button>
          </form>

          <div className="mt-8 text-center text-xs text-gray-400 font-medium">
            &copy; {new Date().getFullYear()} HMA Management System
          </div>
        </div>
      </div>
    );
  }

  // --- Main View ---
  return (
    <div className="flex flex-col h-screen bg-gray-100 font-sans">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white shadow-lg z-30 flex-none">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-3">
              <div className="bg-gradient-to-tr from-amber-400 to-amber-600 p-2 rounded-xl text-slate-900 shadow-md">
                <Scale className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="font-bold text-lg tracking-wide hidden sm:block">Hairi Mustafa Associates</h1>
                <h1 className="font-bold text-lg tracking-wide sm:hidden">HMA System</h1>
                <p className="text-xs text-gray-400">Sistem Kewangan & Invois</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <button onClick={() => setIsInvoiceModalOpen(true)} className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 rounded-xl text-sm font-medium transition flex items-center gap-2 shadow-sm border border-blue-500">
                <FileText className="w-4 h-4" /> <span className="hidden sm:inline">Invois</span>
              </button>
              <button onClick={() => setIsReportModalOpen(true)} className="bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 rounded-xl text-sm font-medium transition flex items-center gap-2 mr-2 shadow-sm border border-purple-500">
                <Table className="w-4 h-4" /> <span className="hidden sm:inline">Laporan</span>
              </button>

              <div className="h-6 w-px bg-slate-700 mx-1"></div>

              <button onClick={handleExport} className="bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 rounded-xl transition shadow-sm border border-emerald-500" title="Backup (Export)">
                <Download className="w-4 h-4" />
              </button>
              <label className="bg-slate-700 hover:bg-slate-600 text-white px-3 py-2 rounded-xl transition cursor-pointer border border-slate-600 shadow-sm" title="Import CSV">
                <Upload className="w-4 h-4" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={handleReset} className="bg-rose-600 hover:bg-rose-700 text-white px-3 py-2 rounded-xl transition ml-2 shadow-sm border border-rose-500" title="Reset Data">
                <Power className="w-4 h-4" />
              </button>
              <button onClick={handleLogout} className="bg-slate-800 hover:bg-slate-700 text-gray-300 hover:text-white px-3 py-2 rounded-xl transition ml-2 border border-slate-700 shadow-sm" title="Log Keluar">
                <LogOut className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Warning Banner */}
      {showBackupAlert && (
        <div className="bg-rose-600 text-white px-4 py-2 text-center shadow-md text-sm font-bold flex items-center justify-center gap-2 animate-in slide-in-from-top-2">
          <AlertCircle className="w-4 h-4 text-yellow-300" />
          PERINGATAN: Sila buat 'Backup' data (Eksport) sekarang.
          <button onClick={handleExport} className="underline text-yellow-200 hover:text-white">Klik Sini</button>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6">
        <div className="max-w-7xl mx-auto space-y-6 pb-20">

          {/* Controls */}
          <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-4 rounded-2xl shadow-sm border border-gray-200 sticky top-0 z-20">
            <div className="flex flex-wrap items-center gap-3 w-full md:w-auto">
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-2.5 rounded-xl border border-indigo-100 shadow-sm">
                <label className="text-xs font-bold text-indigo-800 uppercase flex items-center gap-1">
                  <Filter className="w-3 h-3" /> Papar:
                </label>
                <select 
                  className="bg-transparent font-bold text-indigo-900 focus:outline-none cursor-pointer text-sm"
                  value={filterAccount}
                  onChange={(e) => setFilterAccount(e.target.value)}
                >
                  <option value="all">SEMUA AKAUN</option>
                  {ACCOUNTS.map(a => <option key={a} value={a}>{a}</option>)}
                </select>
              </div>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-800 text-sm rounded-xl px-4 py-2.5 font-semibold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none shadow-sm"
                value={filterYear}
                onChange={(e) => setFilterYear(parseInt(e.target.value))}
              >
                {[currentYear - 1, currentYear, currentYear + 1].map(y => (
                  <option key={y} value={y}>{y}</option>
                ))}
              </select>

              <select 
                className="bg-gray-50 border border-gray-200 text-gray-800 text-sm rounded-xl px-4 py-2.5 font-semibold cursor-pointer hover:bg-white focus:ring-2 focus:ring-indigo-100 focus:border-indigo-500 transition-all outline-none shadow-sm"
                value={filterMonth}
                onChange={(e) => setFilterMonth(parseInt(e.target.value))}
              >
                {MONTHS.map((m, i) => <option key={i} value={i}>{m}</option>)}
              </select>
            </div>

            <button 
              onClick={() => { 
                setEditingTransaction(null); 
                setModalMode('create');
                setIsAddModalOpen(true); 
              }}
              className="w-full md:w-auto bg-slate-900 hover:bg-slate-800 text-white px-6 py-2.5 rounded-xl shadow-lg transition-all font-bold text-sm flex items-center justify-center gap-2 active:scale-95"
            >
              <PlusCircle className="w-4 h-4" /> Rekod Transaksi
            </button>
          </div>

          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
            <div className="bg-white p-5 rounded-2xl shadow-sm border-l-4 border-emerald-500 hover:shadow-md transition-shadow">
              <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Jumlah Masuk</p>
              <p className="text-2xl font-bold text-gray-800 mt-2">{formatRM(totals.in)}</p>
            </div>
            <div className="bg-white p-5 rounded-2xl shadow-sm border-l-4 border-rose-500 hover:shadow-md transition-shadow">
              <p className="text-xs font-bold text-gray-400 uppercase tracking-wide">Jumlah Keluar</p>
              <p className="text-2xl font-bold text-gray-800 mt-2">{formatRM(totals.out)}</p>
            </div>
            <div className="bg-white p-5 rounded-2xl shadow-sm border-l-4 border-indigo-500 hover:shadow-md transition-shadow">
