                          {inv.status === 'unpaid' && (
                            <button onClick={() => onPayInvoice(inv)} className="p-3 text-emerald-600 bg-emerald-50 rounded-xl hover:bg-emerald-100 transition-all border border-emerald-100" title="Terima Bayaran">
                              <Banknote className="w-4 h-4" />
