import React, { useState, useEffect, useMemo } from 'react';
import { 
  Scale, FileText, Table, Download, Upload, Power, 
  Filter, PlusCircle, Trash2, Printer, Copy, Search, AlertCircle, Pencil, Lock, LogOut,
  ArrowRightLeft, TrendingUp, TrendingDown, LayoutDashboard, Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { ACCOUNTS, MONTHS, Transaction, Invoice } from './types';
import { formatRM, formatDate, printReceipt } from './utils/printUtils';

import TransactionFormModal from './components/TransactionFormModal';
import InvoiceModal from './components/InvoiceModal';
import ReportModal from './components/ReportModal';
import AccountStatementModal from './components/AccountStatementModal';

const App: React.FC = () => {
  // --- Auth State ---
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
    return sessionStorage.getItem('hma_auth') === 'true';
  });
  const [passwordInput, setPasswordInput] = useState('');
  const [loginError, setLoginError] = useState('');

  // --- Data State ---
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('hma_db_trans');
    return saved ? JSON.parse(saved) : [];
  });

  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('hma_db_invoices');
    return saved ? JSON.parse(saved) : [];
  });

  // Filters
  const currentYear = new Date().getFullYear();
  const [filterYear, setFilterYear] = useState(currentYear);
  const [filterMonth, setFilterMonth] = useState(new Date().getMonth());
  const [filterAccount, setFilterAccount] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Modals
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [isStatementModalOpen, setIsStatementModalOpen] = useState(false);
  const [modalMode, setModalMode] = useState<'create' | 'edit' | 'copy'>('create');

  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [showBackupAlert, setShowBackupAlert] = useState(false);

  // --- Effects ---
  useEffect(() => {
    localStorage.setItem('hma_db_trans', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    localStorage.setItem('hma_db_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('hma_last_backup');
    const now = Date.now();
    if (!lastBackup || (now - parseInt(lastBackup)) > 7 * 24 * 60 * 60 * 1000) {
      setShowBackupAlert(true);
    } else {
      setShowBackupAlert(false);
    }
  }, []);

  // --- Computed Data ---
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const d = new Date(t.date);
      const matchDate = d.getFullYear() === filterYear && d.getMonth() === filterMonth;
      const matchAcc = filterAccount === 'all' || t.account === filterAccount;
      const matchSearch = searchTerm === '' || 
        (t.name + t.details + t.account + t.category).toLowerCase().includes(searchTerm.toLowerCase());
      return matchDate && matchAcc && matchSearch;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, filterYear, filterMonth, filterAccount, searchTerm]);

  const totals = useMemo(() => {
    let tIn = 0, tOut = 0;
    filteredTransactions.forEach(t => {
      if (t.type === 'in') tIn += t.amount;
      else tOut += t.amount;
    });
    return { in: tIn, out: tOut, bal: tIn - tOut };
  }, [filteredTransactions]);

  // --- Handlers ---
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === '025495') {
      setIsAuthenticated(true);
      sessionStorage.setItem('hma_auth', 'true');
      setLoginError('');
      setPasswordInput('');
    } else {
      setLoginError('Kata laluan tidak sah.');
      setPasswordInput('');
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('hma_auth');
  };

  const handleSaveTransaction = (t: Omit<Transaction, 'id'>) => {
    if (modalMode === 'edit' && editingTransaction) {
      setTransactions(prev => prev.map(tr => 
        tr.id === editingTransaction.id ? { ...t, id: editingTransaction.id } : tr
      ));
    } else {
      const newTrans = { ...t, id: Date.now() };
      setTransactions(prev => [...prev, newTrans]);
    }
    setEditingTransaction(null);
    setModalMode('create');
  };

  const handleDeleteTransaction = (id: number) => {
    if (confirm('Padam transaksi ini?')) {
      setTransactions(prev => prev.filter(t => t.id !== id));
    }
  };

  const handleEdit = (t: Transaction) => {
    setEditingTransaction(t);
    setModalMode('edit');
    setIsAddModalOpen(true);
  };

  const handleAddInvoice = (inv: Omit<Invoice, 'id' | 'status' | 'date'>) => {
    const newInv: Invoice = {
      ...inv,
      id: Date.now(),
      status: 'unpaid',
      date: new Date().toISOString().split('T')[0]
    };
    setInvoices(prev => [...prev, newInv]);
  };

  const handleDeleteInvoice = (id: number) => {
    if (confirm('Padam invois ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const handlePayInvoice = (inv: Invoice) => {
    if (confirm(`Adakah ${inv.client} sudah membuat bayaran RM${inv.amount}?`)) {
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: 'paid' } : i));
      const newTrans: Transaction = {
        id: Date.now(),
        date: new Date().toISOString().split('T')[0],
        type: 'in',
        account: 'Akaun Pejabat',
        amount: inv.amount,
        name: inv.client,
        category: 'Fee',
        details: `Bayaran Invois: ${inv.no}`
      };
      setTransactions(prev => [...prev, newTrans]);
    }
  };

  const handleExport = () => {
    localStorage.setItem('hma_last_backup', Date.now().toString());
    setShowBackupAlert(false);

    const headers = ["Tarikh", "Nama", "Butir-butir", "In", "Out", "Katagori"];
    let csvContent = headers.join(",") + "\n";

    transactions.sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()).forEach(t => {
      const [y, m, d] = t.date.split('-');
      const formattedDate = `${d}/${m}/${y}`;

      const row = [
        formattedDate,
        `"${t.name.replace(/"/g, '""')}"`,
        `"${t.details.replace(/"/g, '""')}"`,
        t.type === 'in' ? `"${t.amount.toFixed(2)}"` : "",
        t.type === 'out' ? `"${t.amount.toFixed(2)}"` : "",
        `"${t.category.replace(/"/g, '""')}"`
      ];
      csvContent += row.join(",") + "\n";
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `HMA_PETTY_CASH_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const content = evt.target?.result as string;
        const lines = content.split(/\r?\n/).filter(line => line.trim() !== "");
        if (lines.length <= 1) return;

        const newTrans: Transaction[] = [];
        const baseId = Date.now();

        for (let i = 1; i < lines.length; i++) {
          const c = lines[i].split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/);
          if (c.length < 5) continue;

          const cleanStr = (val: string) => (val || "").trim().replace(/^"|"$/g, '').replace(/""/g, '"');
          const cleanAmount = (val: string) => {
            if (!val) return NaN;
            const sanitized = val.replace(/RM/gi, '').replace(/,/g, '').trim();
            return parseFloat(sanitized);
          };

          const parseDate = (dateStr: string) => {
            const parts = dateStr.split('/');
            if (parts.length === 3) {
              const d = parts[0].padStart(2, '0');
              const m = parts[1].padStart(2, '0');
              let y = parts[2];
              if (y.length === 2) y = `20${y}`;
              return `${y}-${m}-${d}`;
            }
            return dateStr.includes('-') ? dateStr : null;
          };

          const rawDate = cleanStr(c[0]);
          const name = cleanStr(c[1]);
          const details = cleanStr(c[2]);
          const inVal = cleanAmount(cleanStr(c[3]));
          const outVal = cleanAmount(cleanStr(c[4]));
          const category = cleanStr(c[5]) || "Office";

          const parsedDate = parseDate(rawDate);
          if (!parsedDate) continue;

          let amount = 0;
          let type: 'in' | 'out' = 'in';

          if (!isNaN(inVal) && inVal !== 0) {
            amount = Math.abs(inVal);
            type = 'in';
          } else if (!isNaN(outVal) && outVal !== 0) {
            amount = Math.abs(outVal);
            type = 'out';
          } else continue;

          newTrans.push({
            id: baseId + i + Math.random(),
            date: parsedDate,
            account: "Akaun Pejabat",
            type,
            category,
            name,
            details,
            amount
          });
        }

        if (newTrans.length > 0) {
          setTransactions(prev => [...prev, ...newTrans]);
          alert(`${newTrans.length} rekod diimport!`);
        }
      } catch (err) {
        alert("Ralat import fail.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; 
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-4">
        <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-in fade-in zoom-in-95 border border-slate-200">
          <div className="flex flex-col items-center mb-10">
            <div className="bg-gradient-to-tr from-indigo-600 to-indigo-400 p-5 rounded-[2rem] shadow-xl mb-6 ring-8 ring-indigo-50">
              <Lock className="w-10 h-10 text-white" strokeWidth={2.5} />
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tight">Akses Sistem</h1>
            <p className="text-slate-500 font-semibold mt-1">Hairi Mustafa Associates</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input
              type="password"
              placeholder="Masukkan kata laluan"
              className={`w-full bg-slate-50 border-2 rounded-2xl px-6 py-4 text-center text-xl tracking-[0.3em] font-black outline-none transition-all ${loginError ? 'border-rose-400 bg-rose-50 text-rose-700' : 'border-slate-100 focus:border-indigo-500 focus:bg-white focus:ring-8 focus:ring-indigo-500/10 text-slate-800'}`}
              value={passwordInput}
              onChange={(e) => { setPasswordInput(e.target.value); setLoginError(''); }}
              autoFocus
            />
            {loginError && <p className="text-center text-rose-600 text-sm font-bold animate-pulse">{loginError}</p>}
            <button type="submit" className="w-full bg-slate-900 hover:bg-slate-800 text-white py-4.5 rounded-2xl font-black text-lg transition-all shadow-xl active:scale-[0.98]">Masuk Sekarang</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-[#F0F2F5] font-sans">
      <nav className="bg-[#0A1128] text-white shadow-2xl z-40 flex-none px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
