              <button onClick={() => setIsInvoiceModalOpen(true)} className="p-2.5 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600/30 rounded-xl border border-indigo-600/20 transition-all"><FileText className="w-5 h-5" /></button>
              <button onClick={() => setIsStatementModalOpen(true)} className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-all border border-slate-700"><ArrowRightLeft className="w-5 h-5" /></button>
              <button onClick={() => setIsReportModalOpen(true)} className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-all border border-slate-700"><Table className="w-5 h-5" /></button>
            </div>
            <div className="h-8 w-px bg-white/10 mx-1"></div>
            <div className="flex items-center gap-2">
              <button onClick={handleExport} className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-all border border-slate-700"><Download className="w-5 h-5" /></button>
              <label className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-all border border-slate-700 cursor-pointer">
                <Upload className="w-5 h-5" />
                <input type="file" accept=".csv" className="hidden" onChange={handleImport} />
              </label>
              <button onClick={() => { if(confirm("Hapus semua?")) { setTransactions([]); setInvoices([]); } }} className="p-2.5 bg-rose-600/20 text-rose-500 hover:bg-rose-600/30 rounded-xl border border-rose-600/20 transition-all"><Power className="w-5 h-5" /></button>
