                <select className="w-full bg-slate-50 border-2 border-slate-100 rounded-full px-8 py-4 font-black uppercase tracking-widest text-xs outline-none focus:border-indigo-500 transition-all cursor-pointer" value={filterMonth} onChange={(e) => setFilterMonth(parseInt(e.target.value))}>
