              <input type="text" placeholder="Cari transaksi..." className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-14 py-4 text-sm font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all shadow-inner" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
            </div>
