                </div>
                {errors.name && touched.name && <p className="text-[10px] text-rose-600 font-black uppercase px-2 tracking-widest flex items-center gap-1.5"><AlertCircle className="w-3 h-3" /> {errors.name}</p>}
              </div>

              <div className="space-y-4">
