export const formatRM = (n: number) => "RM " + n.toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Memformat tarikh ke bentuk dd/mm/yyyy
 * Menggunakan pemisahan string untuk ketepatan bagi format YYYY-MM-DD
 */
export const formatDate = (s: string) => {
  if (!s) return "";

  // Jika format adalah YYYY-MM-DD (format standard input date)
  if (s.includes('-')) {
    const parts = s.split('-');
    if (parts.length === 3 && parts[0].length === 4) {
      const [y, m, d] = parts;
      return `${d}/${m}/${y}`;
    }
  }

  // Fallback jika format berbeza
  const d = new Date(s);
  if (isNaN(d.getTime())) return s;
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
};

