                />
              </div>
              {errors.amount && touched.amount && (
                <div className="mt-3 flex items-center gap-1.5 text-rose-600 text-[10px] font-bold uppercase">
                  <AlertCircle className="w-3 h-3" /> {errors.amount}
                </div>
              )}
            </div>

            {/* Primary Fields */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1 flex items-center gap-2">
                  <Calendar className="w-3 h-3" /> Tarikh
                </label>
                <div className="relative group">
                  <input 
                    type="date" 
                    className={`${inputBase} ${touched.date && !errors.date ? 'border-emerald-200' : 'border-slate-100 focus:border-indigo-500'}`} 
                    value={formData.date} 
                    onChange={e => handleChange('date', e.target.value)} 
                  />
                  <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1 flex items-center gap-2">
                  <Wallet className="w-3 h-3" /> Akaun
                </label>
                <div className="relative group">
                  <select
                    className={`${inputBase} border-slate-100 focus:border-indigo-500 appearance-none cursor-pointer`}
                    value={formData.account}
                    onChange={e => handleChange('account', e.target.value)}
                  >
                    {ACCOUNTS.map(acc => <option key={acc} value={acc}>{acc}</option>)}
                  </select>
                  <CreditCard className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 pointer-events-none" />
                </div>
              </div>
            </div>

            {/* Name Input */}
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-400 uppercase ml-1 flex items-center gap-2">
                <User className="w-3 h-3" /> Nama Pihak (Pembayar/Penerima)
              </label>
              <div className="relative group">
                <input 
                  type="text" 
                  placeholder="Masukkan nama..." 
                  className={`${inputBase} ${touched.name && !errors.name ? 'border-emerald-200' : 'border-slate-100 focus:border-indigo-500'}`} 
                  value={formData.name} 
                  onChange={e => handleChange('name', e.target.value)} 
                  onBlur={() => handleBlur('name')} 
                />
                <User className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
              </div>
              {errors.name && touched.name && <p className="text-[10px] text-rose-600 font-bold uppercase px-1">{errors.name}</p>}
            </div>

            {/* Category & Suggestions */}
            <div className="space-y-3">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase ml-1 flex items-center gap-2">
                  <Bookmark className="w-3 h-3" /> Kategori
                </label>
                <div className="relative group">
                  <input 
                    list="categories" 
                    placeholder="Pilih kategori..." 
                    className={`${inputBase} ${touched.category && !errors.category ? 'border-emerald-200' : 'border-slate-100 focus:border-indigo-500'}`} 
                    value={formData.category} 
                    onChange={e => handleChange('category', e.target.value)} 
                    onBlur={() => handleBlur('category')} 
                  />
                  <Tag className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                  <datalist id="categories">
                    {CATEGORIES.map(c => <option key={c} value={c} />)}
                  </datalist>
                </div>
              </div>

              <div className="flex flex-wrap gap-1.5">
                {commonCategories.map(cat => (
                  <button
                    key={cat}
                    type="button"
                    onClick={() => { handleChange('category', cat); setTouched(t => ({ ...t, category: true })); }}
                    className={`text-[9px] font-bold px-3 py-1.5 rounded-lg border transition-all ${
                      formData.category === cat 
                        ? `${isIncome ? 'bg-emerald-600 text-white border-emerald-600' : 'bg-rose-600 text-white border-rose-600'}`
