                 <span className="text-[9px] font-black text-indigo-500 uppercase bg-indigo-50 border border-indigo-100 px-4 py-1.5 rounded-full ring-2 ring-indigo-500/5">{invoices.length} Rekod Sedia Ada</span>
               </div>
