export const formatRM = (n: number) => "RM " + n.toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Memformat tarikh ke bentuk dd/mm/yyyy secara konsisten.
 */
export const formatDate = (s: string | Date | undefined): string => {
  if (!s) return "";

  let d: Date;

  if (s instanceof Date) {
    d = s;
  } else if (typeof s === 'string') {
    // Jika format dd/mm/yyyy sudah betul, pulangkan terus
    if (s.match(/^\d{2}\/\d{2}\/\d{4}$/)) return s;

    // Jika format YYYY-MM-DD (ISO)
    if (s.includes('-')) {
      const parts = s.split('-');
      if (parts.length === 3 && parts[0].length === 4) {
        d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
      } else {
        d = new Date(s);
      }
    } else {
      d = new Date(s);
    }
  } else {
    return "";
  }

  if (isNaN(d.getTime())) return "";

  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${day}/${month}/${year}`;
};

/**
 * Menukarkan format dd/mm/yyyy kembali ke YYYY-MM-DD untuk kegunaan input native
 */
export const toISODate = (s: string): string => {
  if (!s) return "";
  const parts = s.split('/');
  if (parts.length === 3) {
    const [d, m, y] = parts;
    return `${y}-${m}-${d}`;
  }
  return s;
};

