      <TransactionFormModal isOpen={isAddModalOpen} onClose={() => { setIsAddModalOpen(false); setEditingTransaction(null); setModalMode('create'); }} onSave={handleSaveTransaction} initialData={editingTransaction} mode={modalMode} />
