                            <td className="px-10 py-10 text-right font-black text-slate-900 text-xl tabular-nums tracking-tighter">{formatRM(currentRunning)}</td>
                          </tr>
                        );
                      });
                    })()}

                    {filteredTransactions.length === 0 && (
                      <tr>
                        <td colSpan={5} className="py-48 text-center">
